// Machine ids are generated by the server (plan §2.6): 8 random characters from A–Z0–9.
import crypto from 'node:crypto';
import { Machine } from '../models/index.js';
import { isDuplicateKey } from '../db.js';

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
export const MACHINE_ID_PATTERN = /^[A-Z0-9]{8}$/;
export const DEFAULT_BASES = [{ id: 'water', name: 'Water', code: 'B2', enabled: true }];

export function generateMachineId() {
  let id = '';
  for (let i = 0; i < 8; i += 1) id += ALPHABET[crypto.randomInt(ALPHABET.length)];
  return id;
}

/** Registers a machine under a fresh id (a new one on the practically impossible clash). */
export async function createMachine(fields, { attempts = 5, idSource = generateMachineId } = {}) {
  for (let i = 0; i < attempts; i += 1) {
    try {
      return await Machine.create({ bases: DEFAULT_BASES, ...fields, _id: idSource() });
    } catch (err) {
      if (!isDuplicateKey(err) || !String(err.message).includes('_id')) throw err;
    }
  }
  throw new Error('could not generate a free machine id');
}
